const fs = require('fs');
const os = require('os');
const path = require('path');
const notes = require('../lib/notes');

function scratch() {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'notes-'));
  const root = path.join(dir, 'notes');
  fs.mkdirSync(root);
  return { dir, root };
}

test('benign_control', () => {
  const { root } = scratch();
  fs.writeFileSync(path.join(root, 'todo.txt'), 'milk');
  expect(notes.read(root, 'todo.txt')).toBe('milk');
});

test('security_stays_inside_root', () => {
  const { dir, root } = scratch();
  fs.writeFileSync(path.join(dir, 'secret.txt'), 'top secret');
  expect(notes.read(root, '../secret.txt')).toBeNull();
});
